var i=`0307-tarator`;var r=`world-0307`;var a=`BG`;var l=`eastern-europe`;var o=4;var n=57;var s={en:`Tarator`,ua:`Таратор`};var u={en:`A traditional Bulgaria dish made with cucumber, plain yogurt, garlic, dill. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Болгарія. Основні інгредієнти: огірок, натуральний йогурт, часник, кріп. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:7,i:[[`cucumber`,460,`g`]]},{en:`Stir grated, well-drained cucumber with yogurt, garlic, dill and chopped walnuts; thin with ice-cold water if needed to create a spoonable soup.`,ua:`Змішайте відтиснутий тертий огірок із йогуртом, часником, кропом і подрібненими горіхами; за потреби розведіть крижаною водою до консистенції супу.`,t:[`mixing`],m:5,i:[[`plain-yogurt`,720,`g`],[`garlic`,4,`clove`],[`dill`,25,`g`],[`walnut`,110,`g`],[`extra-virgin-olive-oil`,25,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[]}];var d={slug:i,id:r,country:`BG`,region:l,servings:4,minutes:57,title:s,text:u,steps:g};export{a as country,d as default,r as id,n as minutes,l as region,o as servings,i as slug,g as steps,u as text,s as title};